import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))  # noqa: E401,E702
import vmpaths  # noqa: E402
import json, os
W = str(vmpaths.area('skin'))
OUT = str(vmpaths.OUT / 'tex' / 'skin' / 'manifest.json')
m = json.load(open(os.path.join(W, 'manifest_body.json'), encoding='utf-8'))

notes = {
    'paths': 'All texture paths are relative to tools/local. One material per head: the head mesh (and the morph glb) has a single submesh; every texture uses TEXCOORD_0 (UV0) of tools/local/glb/h0_000_p?a__morphs.morphtarget.glb as-is (glTF convention, v=0 at the image top, GLTFLoader default flipY=false). Verified: overlaying UV0 points on the albedo puts eyes/lips/ears on the painted features.',
    'selection': 'Final head material = skinTones[<catalog skin_color app>].byskinType[<catalog skin_type_switcher meshHint>]. The skin TYPE (meshHint h0_000__basehead = d01, _d02.._d05) only swaps the albedo texture (d01 clean, d02 freckles, d03 heavy blemishes/sun spots, d04 smooth/even, d05 flushed cheeks). The skin TONE (catalog app) never changes textures: it only changes tintColor + tintScale (and for *_00_warm_ivory the tint mask). Normal, roughness, detail normal, microdetail and all scalars are identical for every tone/type of a gender.',
    'albedo': 'albedo_d0N.jpg: sRGB base colour (game: TCM_QualityColor, isGamma=1), 1024x1024 in the game, alpha unused (always 255) so stored as JPG q95 4:4:4. Use colorSpace = SRGBColorSpace. Contains the mouth interior (top-left red island = mouth bag / gums area) and eye-corner pieces (top) - these are part of the head mesh, so the open mouth renders correctly with the same material.',
    'tint': 'Skin tone tint (skin.mt TintColor/TintScale/TintColorMask), reconstructed from the WolvenKit Blender add-on skin shader: factor = abs(tintScale) * tintMask.R ; if tintScale >= 0: tinted = albedo * tintColor (multiply) else: tinted = overlay(albedo, tintColor) (overlay: a<0.5 ? 2ab : 1-2(1-a)(1-b)) ; color = mix(albedo, tinted, factor). Do it in LINEAR space (convert tintColor hex from sRGB to linear first, albedo is already linear after sRGB texture decode). Check: linear-space result on the cheek of female d01 matches the catalog UI swatch hues (pale/limestone/beige/senna/amber/honey/band/umber) with a near-constant ~0.87 brightness ratio (the swatches are darker UI chips); sRGB-space multiply matched worse (band, beige, honey off). tintMask.R is 1.0 over the whole face mask and the torso mask, so in practice factor = abs(tintScale) everywhere. The face mask G and B channels are NOT the tint mask: G = microdetail roughness region index (floor(G*6)/6), B = microdetail UV-scale blend (floor(B*5)/5). Game flags the mask as sRGB (isGamma=1); R is 1.0 either way. tintScale 0 (01_ca_pale) = untinted albedo.',
    'normal': 'normal_gl.png etc.: the game normal maps are BC5 two-channel, DirectX convention (+X right, Y DOWN). I CONVERTED every *_gl.png: G inverted (G\' = 1 - G) and Z rebuilt (B = sqrt(1-x^2-y^2) * 0.5 + 0.5), so they are standard OpenGL/glTF tangent-space normal maps: plug straight into MeshStandardMaterial/MeshPhysicalMaterial.normalMap with colorSpace = NoColorSpace (linear) and normalScale (1,1) (if GLTFLoader-style vertex tangents are absent three.js derives tangents from UVs; same UV orientation as glTF so no extra flip). DirectX convention was confirmed empirically: integrability (curl) test on all five normal maps is 2-3x lower with Y-down than with Y-up, and the RED modding wiki says Cyberpunk normals are +X -Y +Z.',
    'roughness': 'rough_detailmask_gl.png is REPACKED from the game rm01 texture (R=roughness, G=metalness(always 0), B=detail mask) into glTF ORM order: R = detail mask (game B), G = roughness (game R), B = metalness (0). So it can be assigned directly to roughnessMap (three.js reads G) and metalnessMap (reads B, all 0; or just set metalness 0). Linear (NoColorSpace). The detail mask (R here) = 1 on the face skin, lower on lips/eyelids/nostrils/ear interior, and gates microdetail + cavity. Game shader (per Blender add-on): finalRough = rough * (1 - mask + mask * mix(DetailRoughnessBiasMin, DetailRoughnessBiasMax sorted lo..hi, microRough)), where microRough = mix(dr1, dr2, smoothstep(floor(tintMask.G*6)/6)), dr = 2.5*(x(1+x)+y(1+y))+0.2 with x,y = microdetail R,G remapped to -1..1. Simple approximation for three.js: roughness = G of the map * ~0.95.',
    'detailNormal': 'detail_normal_gl.png (2048, in head UV0 space, NOT tiled): blend on top of the base normal with weight params.DetailNormalInfluence (0.8). Use UDN/whiteout blend: n = normalize(vec3(base.xy + w*detail.xy, base.z)). Its R channel (-1..1) also darkens cavities in the game (CavityIntensity 0.25 * 0.1, tiny effect - can be skipped).',
    'microDetail': 'common/microdetail_n_gl.png is an ATLAS 1024x512 = two 512x512 tiling pore-normal tiles side by side (left = MicroDetail01, right = MicroDetail02), already converted to OpenGL convention. Per Blender add-on: regionScale = floor(tintMask.B*5)/5; uv1 = fract(uv0 * MicroDetailUVScale01(20) * (regionScale+1.4)) * vec2(0.5,1); uv2 = fract(uv0 * MicroDetailUVScale02(8) * (regionScale+1.0)) * vec2(0.5,1) + vec2(0.5,0); m = mix(sample(uv1), sample(uv2), smoothstep(0,1,floor(tintMask.G*6)/6)); add m.xy * (detailMask * MicroDetailInfluence(0.8)) to the normal. Note fract() on UVs breaks mip selection at tile seams - in a shader compute derivatives from the unfracted UV (textureGrad) or simply set wrapS/wrapT = RepeatWrapping and use the left/right tile as two separate textures (crop the atlas). Cheap approximation: three.js clearcoatNormalMap is not suitable; better a small onBeforeCompile patch, or use only the 20x tile as a detail normal with weight 0.3-0.5.',
    'wrinkles': 'wrinkle_stretch_n_gl.png / wrinkle_squash_n_gl.png (head UV0 space) are expression wrinkle normals, blended in by facial-animation driven influences (stretch/squash). bloodflow_mask.png: R = squash area, G = stretch area (mix colour toward BloodColor, which is #000000 for player heads = no-op). For a static editor you can ignore them, or fade in squash/stretch normals with the mouth-open / smile morph weights (weight^3 for the blood term).',
    'subsurface': 'Material type RMT_Subsurface (skin.mt). Skin profile default.sp: diffuse #ffffff, falloff (scatter colour) #ffb2a5, blurSize 1.4 (screen-space SSS blur, game units ~mm), roughness0 0.966 / roughness1 1.597 with lobeMix 1 (dual-lobe specular: the two lobes use roughness*0.966 and roughness*1.597 - interpretation, not decompiled). three.js suggestion: MeshPhysicalMaterial with sheen 0, specularIntensity ~0.5 (skin F0 ~0.028), and fake SSS via a wrapped-diffuse / transmission tint using falloff #ffb2a5; or MeshPhysicalMaterial.thickness+attenuationColor is not appropriate for opaque skin.',
    'emissive': 'EmissiveMask black, EmissiveEV 0 - no emission.',
    'secondaryAlbedo': 'SecondaryAlbedo unused for player heads (white, influence 0). The game uses it for NPC face tattoos only.',
    'quirks': 'male skinTones h0_000_pma__basehead__01_ca_pale_00_warm_ivory + skin type d05 -> material 01_ca_pale_00_warm_ivory__d05 lacks a mesh-local Normal and falls back to the NPC head normal (male/normal_npc_quirk_gl.png, 512px, from base\\characters\\head\\ma\\h0_001_ma_c__basehead); this is how the game data is, but using the shared player normal is safer. *_00_warm_ivory tones use the TORSO tint mask (32x32 constant R=1,G=0,B=0) instead of the face mask: tint is identical (R=1) but microdetail region/scale indices become 0. Female 05_bl_espresso_d02 inherits from a different .mi (character_mat_instance\\05_bl_espresso.mi with params inlined) - resolved values are identical to the other espresso materials. Head meshes also contain npc_01/02_plastic_doll appearances (multilayered.mt) - not used by the catalog, not exported.',
    'notExported': 'Neck (n0_000_*), body, teeth (ht_000), eyes, brows, lashes, makeup/tattoo/scar overlays are separate meshes handled by other lanes. Albedo/normal/roughness are 1024 in the game (this is the full resolution present in the archive), detail normals 2048, wrinkle maps 512-1024.',
}
m['shaderNotes'] = notes
m['threeQuickStart'] = {
    'material': 'MeshPhysicalMaterial',
    'map': '<gender>.skinTones[app].byskinType[skinType].albedo (SRGBColorSpace) + tint applied in onBeforeCompile after map sampling (diffuseColor.rgb = mix(c, tintScale>=0 ? c*tintLin : overlay(c,tintLin), abs(tintScale)))',
    'cheapTintAlternative': 'if no shader patch: for tintScale >= 0, material.color = linear lerp(white, tintColorLinear, tintScale) gives exactly the multiply formula (mask R = 1 everywhere). Overlay (negative scale, warm_ivory only) needs the shader patch or approximating with color = lerp(white, tintColorLinear*1.15, 0.15).',
    'normalMap': '<gender>.maps.normal (NoColorSpace), normalScale (1,1); optional detailNormal blend 0.8',
    'roughnessMap': '<gender>.maps.roughness (G channel), metalness 0, roughness 1 multiplier',
}
json.dump(m, open(OUT, 'w', encoding='utf-8'), indent=1, ensure_ascii=False)
print(os.path.getsize(OUT))
